(1472, 'ILN-3263', 'LUZON', 'REGION I', 'ILOCOS NORTE', 'CITY OF BATAC', 'CAMANDINGAN', 2007, 17.99201120, '17° 59\' 31.240320\"', 120.54887530, '120° 32\' 55.951080\"', 'ILN-3228 From Batac Town Proper, travel S for about 3 km. along the Nat\'l. Highway until reaching Brgy. Petra Q. Pimentel. Then take a left turn and continue traveling for about 5 km. to reach the station. Station is located inside Pimentel Dam, 8 m. N of the lake and 25 m. S of the gate valve. Mark is the head of a 4 in. copper nail centered and embedded on a 20 cm. x 20 cm. concrete monument, with inscriptions \"ILN-3228 2007 NAMRIA\".', 2007, 'PRS92 Densification', 0.00, 18.07171081, '18° 4\' 18.158910\"', 120.61889480, '120° 37\' 8.021100\"', 0.0000, '0', 94.0510, 0.0000, '4', 56.8964, 247973.04770, 1999744.56100, '51', 18.07343918, '18° 4\' 24.381030\"', 120.61761600, '120° 37\' 3.417620\"', 62.0607, 1998931.70400, 459521.62000, '3', 247836.45800, 1999817.24100, '51', 0.00000000, '0° 0\' 0.000000\"', 0.00000000, '0° 0\' 0.000000\"', 0.0000, 0.0000, 0.0000, '1999-01-01', 'Aila Leana Sampana', '2021-01-01 00:00:00', ''),
(1473, 'ILN-3230', 'LUZON', 'REGION I', 'ILOCOS NORTE', 'CITY OF BATAC', 'MAGNUANG', 2007, 17.99227690, '17° 59\' 32.196840\"', 120.54846960, '120° 32\' 54.490560\"', 'ILN-3229 From Batac Town Proper, travel S for about 3 km. along the Nat\'l. Highway until reaching Brgy. Petra Q. Pimentel. Then take a left turn and continue traveling for about 5 km. to reach the station. Station is located inside Pimentel Dam, 8 m. N of station ILN-3228 and at the W corner of the irrigation spillway and the access road N of the lake. Mark is the head of a 4 in. copper nail centered and embedded on a 20 cm. x 20 cm. concrete monument, with inscriptions \"ILN-3229 2007 NAMRIA\".', 2007, 'PRS92 Densification', 0.00, 18.01905996, '18° 1\' 8.615850\"', 120.53254410, '120° 31\' 57.158760\"', 0.0000, '0', 78.2800, 0.0000, '4', 41.5247, 238750.97340, 1994035.14500, '51', 18.02078704, '18° 1\' 14.833350\"', 120.53126400, '120° 31\' 52.550450\"', 46.3251, 1993125.62400, 450365.65800, '3', 238614.14600, 1994108.06500, '51', 0.00000000, '0° 0\' 0.000000\"', 0.00000000, '0° 0\' 0.000000\"', 0.0000, 0.0000, 0.0000, '1999-01-01', 'TIM', '2022-01-01 00:00:00', ''),
